import React, {useState} from "react";
import api from "../api";

export default function Admissions(){
  const [form,setForm] = useState({studentName:"",parentName:"",classApplied:"",age:"",phone:"",email:"",address:""});
  const [status,setStatus] = useState("");

  const change = e => setForm(f=>({...f,[e.target.name]:e.target.value}));

  const submit = async (e) => {
    e.preventDefault();
    setStatus("Submitting...");
    try{
      const res = await api.post("/admission", form);
      setStatus("Application submitted. We'll contact you.");
      setForm({studentName:"",parentName:"",classApplied:"",age:"",phone:"",email:"",address:""});
    }catch(err){
      console.error(err);
      setStatus("Failed to submit. Try again later.");
    }
  }

  return (
    <div className="container">
      <div className="card">
        <h2 style={{color:"#005baa"}}>Admissions</h2>
        <form onSubmit={submit} style={{marginTop:12}}>
          <input className="form-control" name="studentName" placeholder="Student Name" value={form.studentName} onChange={change} required/>
          <input className="form-control" name="parentName" placeholder="Parent/Guardian Name" value={form.parentName} onChange={change}/>
          <input className="form-control" name="classApplied" placeholder="Class Applied For" value={form.classApplied} onChange={change}/>
          <input className="form-control" name="age" placeholder="Age" value={form.age} onChange={change}/>
          <input className="form-control" name="phone" placeholder="Phone" value={form.phone} onChange={change}/>
          <input className="form-control" name="email" placeholder="Email" value={form.email} onChange={change}/>
          <textarea className="form-control" name="address" placeholder="Address" value={form.address} onChange={change}/>
          <button className="btn" type="submit">Apply</button>
          <div style={{marginTop:8}}>{status}</div>
        </form>
      </div>
    </div>
  )
}
